add_filter('the_content', 'bk_final_fixed_toc', 20);
function bk_final_fixed_toc($content) {
    if (!is_singular('post') || is_admin() || stripos($content, '<h2') === false) return $content;

    // Use a simpler approach to avoid image resizing issues
    $pattern = '/<h2[^>]*>(.*?)<\/h2>/i';
    if (preg_match_all($pattern, $content, $matches)) {
        $toc_html = '<details class="bk-toc-wrapper" open><summary class="bk-toc-summary">Table of Contents</summary><ul class="bk-toc-list">';
        foreach ($matches[1] as $i => $text) {
            $id = 'section-' . ($i + 1);
            $content = preg_replace('/' . preg_quote($matches[0][$i], '/') . '/', '<h2 id="' . $id . '">' . $text . '</h2>', $content, 1);
            $toc_html .= '<li><a href="#' . $id . '">' . strip_tags($text) . '</a></li>';
        }
        $toc_html .= '</ul></details>';

        // Insert TOC before first H2
        $first_h2_pos = strpos($content, '<h2');
        $content = substr_replace($content, $toc_html, $first_h2_pos, 0);
    }
    return $content;
}
